"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[24734],{24734:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/too-loud-a-solitude.png\\"\\n          title=\\"너무 시끄러운 고독\\"\\n          author=\\"보후밀 흐라발\\"\\n          publisher=\\"문학동네\\"\\n          publishedDate=\\"2016-07-08\\"\\n          isbn=\\"9788954641548\\"\\n          rating=4.5\\n          tags=\\"novel\\"\\n        />\\n</center>\\n\\n## Review\\n책 도입에는 솔직히 내용을 정확히 이해하지 못한 채 읽어 내려갔다.  \\n하지만 점점 주인공의 <mark>고독</mark>이 느껴졌다.  \\n책 제목이 너무 마음에 든다. 이 책을 통해 전달하려는 내용이 잘 드러난 제목이다.  \\n<br>\\n```노인을 위한 나라는 없다```가 생각나는 책이다.  \\n<br>\\nAI 시대가 찾아오며, 나 또한 비슷한 감정을 느끼고 있다.  \\n<br>\\n기회가 되면 다시 읽어보면 좋을 것 같은 그런 나만의 추천 책"}')}}]);